const input=$json;
const trigger=String(input.trigger_type ?? '');
const eventId=input.customer_event_id;
const current=input.current_art ?? null;
const actor=String(input.actor_type ?? 'system').toLowerCase();

const choiceAliases={
  'APROVADA':'approved',
  'APPROVED':'approved',
  'PEDIU_ALTERAÇÃO':'change_requested',
  'PEDIU_ALTERACAO':'change_requested',
  'CHANGE':'change_requested',
  'QUESTION':'question',
  'DUVIDA':'question',
  'DÚVIDA':'question',
  'UNDEFINED':'undefined',
  'INDEFINIDO':'undefined'
};
const canonicalChoices=['approved','change_requested','question','undefined'];

if(trigger==='event_won'){
  if(input.art_required!==true){
    return {json:{
      status:'not_applicable',
      operations:[{
        action:'UPSERT_MODULE_STATE',
        customer_event_id:eventId,
        module_code:'art',
        status:'not_applicable',
        ready:true
      }],
      blockers:[]
    }};
  }
  if(current){
    return {json:{status:'no_action',operations:[],blockers:[]}};
  }
  return {json:{
    status:'planned',
    operations:[
      {action:'CREATE_ART_JOB',customer_event_id:eventId,status:'awaiting_briefing',version:1},
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'art',status:'in_progress',ready:false}
    ],
    blockers:[]
  }};
}

if(trigger==='briefing_received'){
  if(!input.briefing_payload || typeof input.briefing_payload!=='object'){
    return {json:{status:'blocked',operations:[],blockers:['ART_BRIEFING_MISSING']}};
  }
  return {json:{
    status:'adapter_required',
    operations:[
      {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,status:'generating',briefing_payload:input.briefing_payload},
      {action:'CREATE_HUMAN_TASK',customer_event_id:eventId,task_type:'art_production',reason_code:'ART_DRAFT_REQUIRED'}
    ],
    blockers:['ART_PRODUCTION_ADAPTER_NOT_CONNECTED']
  }};
}

if(trigger==='draft_ready'){
  if(!input.draft_ref){
    return {json:{status:'blocked',operations:[],blockers:['ART_DRAFT_REF_MISSING']}};
  }
  return {json:{
    status:'planned',
    operations:[
      {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,status:'awaiting_customer',draft_ref:input.draft_ref},
      {action:'EMIT_EVENT',event_type:'art_draft_ready',customer_event_id:eventId},
      {action:'REQUEST_ART_CUSTOMER_REVIEW',customer_event_id:eventId,draft_ref:input.draft_ref}
    ],
    blockers:[]
  }};
}

if(trigger==='customer_message'){
  const raw=String(input.jev_choice ?? '').trim();
  if(!raw){
    return {json:{
      status:'model_required',
      allowed_choices:canonicalChoices,
      operations:[{action:'CALL_JEV',purpose:'art_customer_decision',allowed_choices:canonicalChoices}],
      blockers:['JEV_NOT_CONNECTED']
    }};
  }
  const choice=choiceAliases[raw.toUpperCase()] ?? raw.toLowerCase();
  if(!canonicalChoices.includes(choice)){
    return {json:{
      status:'human_required',
      allowed_choices:canonicalChoices,
      operations:[{action:'CREATE_HUMAN_TASK',customer_event_id:eventId,task_type:'art_review',reason_code:'ART_CHOICE_OUT_OF_VOCABULARY'}],
      blockers:['ART_CHOICE_OUT_OF_VOCABULARY']
    }};
  }

  if(choice==='approved'){
    return {json:{
      status:'pre_approved',
      decision:choice,
      operations:[
        {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,status:'pre_approved',customer_decision:'approved'},
        {action:'CREATE_HUMAN_TASK',customer_event_id:eventId,task_type:'art_final_review',reason_code:'CUSTOMER_PRE_APPROVED_ART'}
      ],
      blockers:[]
    }};
  }
  if(choice==='change_requested'){
    return {json:{
      status:'human_review',
      decision:choice,
      operations:[
        {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,status:'human_revision',customer_decision:'change_requested'},
        {action:'CREATE_HUMAN_TASK',customer_event_id:eventId,task_type:'art_revision',reason_code:'CUSTOMER_CHANGE_REQUESTED'}
      ],
      blockers:[]
    }};
  }
  if(choice==='question'){
    return {json:{
      status:'question',
      decision:choice,
      operations:[
        {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,customer_decision:'question'},
        {action:'REQUEST_ART_QUESTION_RESPONSE',customer_event_id:eventId}
      ],
      blockers:[]
    }};
  }
  return {json:{
    status:'undefined',
    decision:choice,
    operations:[
      {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,customer_decision:'undefined'},
      {action:'ASK_ART_CLARIFICATION',customer_event_id:eventId}
    ],
    blockers:[]
  }};
}

if(trigger==='human_finalize'){
  if(actor!=='human'){
    return {json:{status:'denied',operations:[],blockers:['ART_FINAL_REQUIRES_HUMAN']}};
  }
  if(!input.final_ref){
    return {json:{status:'blocked',operations:[],blockers:['ART_FINAL_REF_MISSING']}};
  }
  return {json:{
    status:'final',
    operations:[
      {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,status:'final',final_ref:input.final_ref},
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'art',status:'completed',ready:true},
      {action:'EMIT_EVENT',event_type:'art_final',customer_event_id:eventId}
    ],
    blockers:[]
  }};
}

if(trigger==='human_cancel'){
  if(actor!=='human'){
    return {json:{status:'denied',operations:[],blockers:['ART_CANCEL_REQUIRES_HUMAN']}};
  }
  return {json:{
    status:'cancelled',
    operations:[
      {action:'UPDATE_ART_JOB',art_job_id:current?.id ?? null,status:'cancelled'},
      {action:'UPSERT_MODULE_STATE',customer_event_id:eventId,module_code:'art',status:'blocked',ready:false,blockers:['ART_CANCELLED']}
    ],
    blockers:[]
  }};
}

return {json:{status:'blocked',operations:[],blockers:['ART_TRIGGER_UNKNOWN']}};
